struct Graph {DiagnosticGraph g;unsigned x,ga,be,eps,dy,y,h,iv,dx,dg,db,receipt=~0u,br=~0u;bool selected,observe,tap;double finalizeUs=0,firstUs=0;
 Graph(bool s,bool o,bool t):g(std::string(s?"s2":"base")+(o?"Obs":"Free")+(t?"Tap":"Native")),selected(s),observe(o),tap(t){
  x=g.tensor("x",QNN_TENSOR_TYPE_APP_WRITE,{1,1,32,64});ga=g.tensor("ga",QNN_TENSOR_TYPE_APP_WRITE,{1,1,1,64});be=g.tensor("be",QNN_TENSOR_TYPE_APP_WRITE,{1,1,1,64});eps=g.tensor("eps",QNN_TENSOR_TYPE_APP_WRITE,{1,1,1,1});dy=g.tensor("dy",QNN_TENSOR_TYPE_APP_WRITE,{1,1,32,64});
  y=g.tensor("y",QNN_TENSOR_TYPE_APP_READ,{1,1,32,64});h=g.tensor("h",tap?QNN_TENSOR_TYPE_APP_READ:QNN_TENSOR_TYPE_NATIVE,{1,1,32,64});iv=g.tensor("iv",tap?QNN_TENSOR_TYPE_APP_READ:QNN_TENSOR_TYPE_NATIVE,{1,1,32,1});
  dx=g.tensor("dx",QNN_TENSOR_TYPE_APP_READ,{1,1,32,64});dg=g.tensor("dg",QNN_TENSOR_TYPE_APP_READ,{1,1,1,64});db=g.tensor("db",QNN_TENSOR_TYPE_APP_READ,{1,1,1,64});std::vector<unsigned> outputs={y,h,iv};if(observe){receipt=g.tensor("receipt",QNN_TENSOR_TYPE_APP_READ,{1,1,1,6313},QNN_DATATYPE_INT_32);outputs.push_back(receipt);}
  g.node("forward",s?(o?"S2":"S2NoReceipt"):(o?"Baseline":"BaselineNoReceipt"),"HexaSelectiveLn1",{x,ga,be,eps},outputs);
  std::vector<unsigned> grad={dx,dg,db};if(observe){br=g.tensor("backward_receipt",QNN_TENSOR_TYPE_APP_READ,{1,1,1,6248},QNN_DATATYPE_INT_32);grad.push_back(br);}g.node("local_backward",o?"LnBackward":"LnBackwardNoReceipt","HexaFp32",{dy,ga,h,iv},grad);auto start=std::chrono::steady_clock::now();g.finalize();finalizeUs=std::chrono::duration<double,std::micro>(std::chrono::steady_clock::now()-start).count();
 }
 std::map<unsigned,std::vector<uint32_t>> run(const s2fixture::Case& c){auto result=g.run({{x,c.x},{ga,c.ga},{be,c.be},{eps,{1e-5f}},{dy,c.dy}});if(!firstUs)firstUs=g.executeUs;return result;}
};
unsigned compare(const std::vector<uint32_t>& a,const std::vector<float>& b){if(a.size()!=b.size())std::exit(3);unsigned n=0;for(unsigned i=0;i<a.size();++i)n+=a[i]!=word(b[i]);return n;}
