  std::printf("{\"kind\":\"performance\",\"s2\":%d,\"observed\":%d,\"tap\":%d,\"samples\":31,\"finalize_us\":%.3f,\"first_execute_us\":%.3f,\"steady_median_us\":%.3f,\"p10_us\":%.3f,\"p90_us\":%.3f,\"arithmetic_median_us\":%.3f,\"receipt_inclusive_median_us\":%.3f,\"nodes\":%u,\"tensors\":%zu,\"native_logical_bytes\":%u,\"host_buffer_lower_bound_bytes\":%u,\"explicit_center_scratch_bytes\":512}\n",g.selected,g.observe,g.tap,g.finalizeUs,g.firstUs,percentile(wall,.5),percentile(wall,.1),percentile(wall,.9),g.observe?percentile(math,.5):0,g.observe?percentile(receipt,.5):0,g.g.nodes,g.g.tensors.size(),nativeBytes,hostBytes);
